Subroutine Suspendable Cocinar(cantidad As Integer, mostrador As Channel<Integer>)
  For pedido <- 1 To cantidad Do
    Define aceptado As Boolean <- Await mostrador.send(pedido);
    If Not aceptado Then
      Write "El mostrador cerró";
    EndIf
  EndFor
EndSubroutine

Algorithm Pedidos
  Define cantidad As Integer;
  Read cantidad;
  Define mostrador As Channel<Integer> <- channel(2);
  Tasks
    Spawn Cocinar(cantidad, mostrador);
    Define entregados As Integer <- 0;
    Repeat
      Switch Await mostrador.receive() Do
        Some(pedido):
          Write "Entrego el pedido ", pedido;
          entregados <- entregados + 1;
        None: Break;
      EndSwitch
    Until False
    Write "Entregados: ", entregados;
  EndTasks
EndAlgorithm

